import csv, hashlib, io, json
from pathlib import Path

root = Path('products/services/agency-launch-qa-pilot')
reports = {}
for name in ('partner-pilot-report-sample.csv', 'buyer-report-control.csv'):
    raw = (root / name).read_bytes()
    rows = list(csv.reader(io.StringIO(raw.decode('utf-8-sig'), newline=''), strict=True))
    if not rows or not rows[0]:
        raise ValueError(f'Empty CSV: {name}')
    header, *body = rows
    reports[name] = {
        'sha256': hashlib.sha256(raw).hexdigest(),
        'header': header,
        'row_count': len(body),
        'row_widths': [len(row) for row in body],
        'fields_for_review': [
            {key: value for key, value in zip(header, row) if any(term in key.casefold() for term in ('outcome', 'status', 'classification', 'result', 'fixture'))}
            for row in body
        ],
    }
expected = '42f21b5f3bb854c6b4c77e1dc40f3af2b406b5d036f4fcdfe5fbf8baf467c48e'
evidence = {
    'reports': reports,
    'partner_sample_matches_prior_receipt': reports['partner-pilot-report-sample.csv']['sha256'] == expected,
    'scope': 'Offline report readback for the failed shape check. No buyer links checked, no browser execution, and no intake or delivery verified.',
}
output = root / 'partner-report-shape-readback.json'
output.write_text(json.dumps(evidence, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
